package com.sanora.giltune

import org.junit.Assert.*
import org.junit.Test
import org.json.JSONObject

/** Kotlin engine == web/js/engine.js on fixtures generated by tools/gen_engine_fixtures.js. */
class SceneEngineEquivalenceTest {
    private val r = TestRules.load()
    private val fx = JSONObject(javaClass.classLoader!!.getResource("engine_fixtures.json")!!.readText())
    private fun JSONObject.dbl(k: String): Double? = if (isNull(k)) null else getDouble(k)
    private fun JSONObject.str(k: String): String? = if (isNull(k)) null else getString(k)

    @Test fun sameRulesVersion() = assertEquals(fx.getInt("rulesVersion"), r.version)

    @Test fun pickSceneMatchesJs() {
        val a = fx.getJSONArray("scenes")
        for (i in 0 until a.length()) {
            val o = a.getJSONObject(i); val c = o.getJSONObject("ctx")
            val ctx = SceneInput(c.getString("roadType"), c.getBoolean("rain"), c.getBoolean("coastal"), c.getBoolean("river"),
                c.getInt("hour"), c.dbl("speedMps"))
            assertEquals("case $i $c", o.getString("expect"), ScenePicker.pick(ctx, r).id)
        }
        assertTrue(a.length() >= 400)
    }

    @Test fun classifyOsmMatchesJs() {
        val a = fx.getJSONArray("osm")
        for (i in 0 until a.length()) {
            val o = a.getJSONObject(i); val els = o.getJSONArray("elements")
            val list = (0 until els.length()).map { k -> val t = els.getJSONObject(k).getJSONObject("tags"); t.keys().asSequence().associateWith { t.getString(it) } }
            val got = RoadClassifier.classify(list, o.dbl("speedMps"), r)
            val e = o.getJSONObject("expect")
            assertEquals("case $i", e.getString("roadType"), got.type.name)
            assertEquals("case $i", e.str("roadName"), got.name)
            assertEquals("case $i", e.getBoolean("river"), got.river)
            assertEquals("case $i", e.getBoolean("coastal"), got.coastal)
        }
    }

    @Test fun stabilizerMatchesJs() {
        val a = fx.getJSONArray("stab")
        for (i in 0 until a.length()) {
            val s = SceneStabilizer(r); val steps = a.getJSONArray(i)
            for (k in 0 until steps.length()) {
                val st = steps.getJSONObject(k); val e = st.getJSONObject("expect")
                val got = s.propose(st.getString("id"), st.getLong("t"))
                assertEquals("seq $i step $k", e.getString("id"), got.id)
                assertEquals("seq $i step $k", e.getBoolean("changed"), got.changed)
            }
        }
    }

    private fun ctxOf(c: JSONObject) = PlanContext(c.getLong("now"), java.time.ZoneId.of("Asia/Seoul"),
        if (c.isNull("wxCode")) null else c.getInt("wxCode"), null, c.getBoolean("rain"), c.dbl("tempC"),
        c.getLong("sunrise"), c.getLong("sunset"), c.dbl("speedMps"), c.getBoolean("jam"), c.getDouble("driveMin"),
        c.str("sceneLabel"), c.getJSONArray("roadReasons").let { a -> (0 until a.length()).map { a.getString(it) } })
    @Test fun plansMatchJs() {
        val a = fx.getJSONArray("plans")
        for (i in 0 until a.length()) {
            val o = a.getJSONObject(i); val rs = o.getJSONArray("rs"); var k = 0
            val got = QueryPlanner.buildPlans(Scene.byId(o.getString("scene"))!!, TasteProfile.fromJson(o.getJSONObject("profile").toString()), r,
                ctxOf(o.getJSONObject("ctx"))) { rs.getDouble(k++) }
            val e = o.getJSONArray("expect")
            assertEquals("case $i", e.length(), got.size)
            for (j in got.indices) { val x = e.getJSONObject(j)
                assertEquals("case $i/$j", x.getString("q"), got[j].q); assertEquals(x.getString("key"), got[j].key)
                assertEquals(x.str("moodKey"), got[j].moodKey); assertEquals(x.getInt("offset"), got[j].offset)
                assertEquals(x.getDouble("weight"), got[j].weight, 1e-9)
                val rj = x.getJSONArray("reason"); assertEquals("case $i/$j reason", (0 until rj.length()).map { rj.getString(it) }, got[j].reason) }
        }
        assertTrue(a.length() >= 100)
    }
}

/** Hand-written cases copied from web/test/engine.test.js. */
class SceneLogicTest {
    private val r = TestRules.load()
    private fun H(h: String, vararg x: Pair<String, String>) = mapOf("highway" to h) + x
    private fun ctx(road: String = "DOWNTOWN", hour: Int = 14, speed: Double? = 12.0, rain: Boolean = false, coastal: Boolean = false, river: Boolean = false) =
        SceneInput(road, rain, coastal, river, hour, speed)

    @Test fun classify() {
        assertEquals(RoadType.MOTORWAY, RoadClassifier.classify(listOf(H("motorway")), 25.0).type)
        assertEquals(RoadType.URBAN_EXPRESSWAY, RoadClassifier.classify(listOf(H("trunk"), H("residential")), 20.0).type)
        assertEquals("양화대교", RoadClassifier.classify(listOf(H("primary", "bridge" to "yes", "name" to "양화대교")), 15.0).name)
        assertEquals(RoadType.BRIDGE, RoadClassifier.classify(listOf(H("primary"), H("primary", "bridge" to "yes")), 15.0).type)
        assertEquals(RoadType.TUNNEL, RoadClassifier.classify(listOf(H("motorway", "tunnel" to "yes")), 25.0).type)
        assertEquals(RoadType.UNKNOWN, RoadClassifier.classify(emptyList(), 10.0).type)
        assertEquals(RoadType.ALLEY, RoadClassifier.classify(listOf(H("motorway"), H("residential")), 3.0).type)
        val w = RoadClassifier.classify(listOf(H("primary"), mapOf("waterway" to "river"), mapOf("natural" to "coastline")), 15.0)
        assertTrue(w.river && w.coastal)
    }
    @Test fun scenePriority() {
        assertEquals("DOWNTOWN", ScenePicker.pick(ctx()).id)
        assertEquals("TUNNEL", ScenePicker.pick(ctx(road = "TUNNEL", rain = true)).id)
        assertEquals("RAIN", ScenePicker.pick(ctx(rain = true)).id)
        assertEquals("COASTAL", ScenePicker.pick(ctx(coastal = true)).id)
        assertEquals("RIVERSIDE", ScenePicker.pick(ctx(river = true)).id)
        assertEquals("ALLEY", ScenePicker.pick(ctx(road = "ALLEY", river = true)).id)
        assertEquals("DOWNTOWN", ScenePicker.pick(ctx(hour = 22)).id)
        assertEquals("HIGHWAY", ScenePicker.pick(ctx(road = "UNKNOWN", speed = 30.0)).id)
        assertEquals("CRUISE", ScenePicker.pick(ctx(road = "UNKNOWN", speed = 5.0)).id)
    }
    @Test fun throttle() {
        val t = QueryThrottle(15_000, 150.0, 180_000)
        assertTrue(t.shouldQuery(0, 37.5, 127.0)); t.mark(0, 37.5, 127.0)
        assertFalse(t.shouldQuery(20_000, 37.5005, 127.0))
        assertTrue(t.shouldQuery(20_000, 37.502, 127.0))
        assertFalse(t.shouldQuery(5_000, 37.51, 127.0))
        t.backoff(20_000, 60_000); assertFalse(t.shouldQuery(30_000, 37.6, 127.0))
        assertEquals(111_195.0, QueryThrottle.distanceMeters(0.0, 0.0, 1.0, 0.0), 50.0)
    }
    @Test fun stabilizer() {
        val s = SceneStabilizer(r)
        assertTrue(s.propose("DOWNTOWN", 0).changed)
        assertFalse(s.propose("ALLEY", 5_000).changed)
        assertFalse(s.propose("ALLEY", 10_000).changed)
        assertTrue(s.propose("ALLEY", 41_000).changed)
        assertFalse(s.propose("BRIDGE", 42_000).changed)
        assertTrue(s.propose("BRIDGE", 45_000).changed)
    }
    @Test fun rulesAreUsedNotHardcoded() {
        assertEquals(2.5, r.drivingMps, 0.0)
        assertEquals(listOf("TUNNEL", "BRIDGE", "RAIN", "COASTAL", "RIVERSIDE", "HIGHWAY", "CITY_EXPRESS", "ALLEY", "DOWNTOWN", "CRUISE"),
            Scene.all().map { it.id })
        assertTrue(S("HIGHWAY").keywords.isNotEmpty())
    }
}

/** NaviHelper TBT -> upcoming segment (prepare next track). */
class RoutePredictorTest {
    private fun t(type: String, d: Double, desc: String? = null) = RoutePredictor.Tbt(type, d, desc)
    @Test fun tunnelAhead() = assertEquals("TUNNEL", RoutePredictor.next(listOf(t("TURN_RIGHT", 300.0), t("TURN_TUNNEL", 900.0)))?.sceneId)
    @Test fun bridgeFromGuidanceText() = assertEquals("BRIDGE", RoutePredictor.next(listOf(t("TURN_STRAIGHT", 600.0, "양화대교 방면")))?.sceneId)
    @Test fun schoolOrCrossingIsNotBridge() = assertNull(RoutePredictor.next(listOf(t("TURN_LEFT", 200.0, "학교 앞 교차로"))))
    @Test fun icEntryIsHighway() = assertEquals("HIGHWAY", RoutePredictor.next(listOf(t("TURN_ENTER_IC_R", 1200.0)))?.sceneId)
    @Test fun nearestWinsAndHorizon() {
        assertEquals(400, RoutePredictor.next(listOf(t("TURN_ENTER_IC_L", 1500.0), t("TURN_TUNNEL", 400.0)))?.distanceM)
        assertNull(RoutePredictor.next(listOf(t("TURN_TUNNEL", 5000.0))))
        assertNull(RoutePredictor.next(emptyList()))
    }
}

/** Fake GPS route through the whole Kotlin pipeline (Yanghwa bridge geofence + OSM fixture roads). */
class FakeRouteSimulationTest {
    init { TestRules.load() }
    data class Step(val sample: PositionSample, val road: RoadInfo)
    private fun road(t: RoadType, river: Boolean = false) = RoadInfo(t, null, false, "fixture", river)
    private fun simulate(steps: List<Step>, hour: Int, rainy: (Int) -> Boolean = { false }): List<String> {
        val engine = RoadEngine(); val stab = SceneStabilizer(); val rec = RuleBasedRecommendationEngine()
        return steps.mapIndexed { i, st ->
            val now = i * 5_000L
            val zone = engine.update(st.sample, now).currentZone
            stab.propose(rec.recommend(SceneContext(zone, rainy(i), hour, st.road, st.sample.speedMps)).id, now).id
        }
    }
    private val route: List<Step> = buildList {
        for (i in 0 until 12) add(Step(PositionSample(37.5300 + i * 0.0003, 126.8800 + i * 0.0010, 8f, 19.5f), road(RoadType.URBAN_EXPRESSWAY)))
        for (lat in listOf(37.5414, 37.5421, 37.5445, 37.5467)) add(Step(PositionSample(lat, 126.9015, 6f, 14f), road(RoadType.DOWNTOWN, true)))
        for (i in 0 until 12) add(Step(PositionSample(37.5530 + i * 0.0004, 126.9070, 8f, 11f), road(RoadType.DOWNTOWN)))
        for (i in 0 until 12) add(Step(PositionSample(37.5600 + i * 0.0001, 126.9100, 8f, 3f), road(RoadType.ALLEY)))
    }
    @Test fun daytimeRoute() {
        val s = simulate(route, 14)
        assertEquals("CITY_EXPRESS", s[0]); assertEquals("CITY_EXPRESS", s[11])
        assertTrue(s.subList(12, 17).contains("BRIDGE"))
        assertTrue(s.subList(17, 28).contains("DOWNTOWN"))
        assertEquals("ALLEY", s.last())
        assertTrue(s.zipWithNext().count { (a, b) -> a != b } <= 4)
    }
    @Test fun nightOnCityRoad() = assertEquals("DOWNTOWN", simulate(route.subList(17, 28), 22).last())
}
